class TextEditor {
    string left, right; // right stored in reverse order
public:
    TextEditor() {

    }

    void addText(string text) {
        left += text;
    }

    int deleteText(int k) {
        int actual = min(k, (int)left.size());
        left.resize(left.size() - actual);
        return actual;
    }

    string cursorLeft(int k) {
        int move = min(k, (int)left.size());
        for (int i = 0; i < move; i++) {
            right.push_back(left.back());
            left.pop_back();
        }
        int len = min(10, (int)left.size());
        return left.substr(left.size() - len);
    }

    string cursorRight(int k) {
        int move = min(k, (int)right.size());
        for (int i = 0; i < move; i++) {
            left.push_back(right.back());
            right.pop_back();
        }
        int len = min(10, (int)left.size());
        return left.substr(left.size() - len);
    }
};
